doc:
\Imga̍k(
	[
		Imkuí([1 2 3 5 3 2 1 ø] ga̍kkhì: Ga̍kkhì.ti̍ká)
		Imkuí(
			[{1𝅝 3 5} {5𝅝 7 9}]
			ga̍kkhì: Ga̍kkhì.kongkhîm
			imliōng: 50%
		)
	]
)\

\Bútâi(
	[
		Kù('up' ētàngkíng: ⊤ miâ: 'up' uītì: Uītì(-2m 0m))
		Kù('tshù' ētàngkíng: ⊤ miâ: 'tshù' uītì: Uītì(2m 0m))
		Imga̍k(
			Imkuí([1 3 5 8 5 3])
			kiān: (Suánti̍k() = 'up' ? 2semitones 0semitones)
		)
	]
)\

\Bútâi(
	[
		Kù('hold' ētàngkíng: ⊤ miâ: 'hold' uītì: Uītì(-2m 0m))
		Kù('go' ētàngkíng: ⊤ miâ: 'go' uītì: Uītì(2m 0m))
		Imga̍k(
			Imkuí([1 3 5 8 5 3] ga̍kkhì: Ga̍kkhì.kongkhîm)
			thîngtùn: Suánti̍k() = 'hold'
		)
	]
)\

\cell: [1 3 5 3]
Imga̍k(
	Imkuí(
		cell
		.kapTshingtuann(
			cell.huani̍k(ƒ(n2•#) n2 + 2)
		)
		.kapTshingtuann(
			cell.tòtńgê()
		)
		.kapTshingtuann(
			cell.huani̍k(ƒ(n3•#) 8 - n3)
		)
		ga̍kkhì: Ga̍kkhì.kongkhîm
	)
)\

\Kù(
	'hāi'
	hiohkhùn: Sūnsū(
		{0%: Tsusè(suântsuán: 360°) 100%: Tsusè(suântsuán: 0°)}
	)\🪲
